{
 "genere": "prevedi",
 "titolo": "Cosa restituisce?",
 "consegna": "Leggi ogni pezzo di codice GDScript legato alla gestione dei parametri dello shader e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted


func run():
	var progress: float = 1.2
	var clamped_progress: float = clamp(progress, 0.0, 1.0)
	return clamped_progress
",
   "domanda": "Quanto vale `clamped_progress` alla fine?",
   "spiegazione": "La funzione `clamp` limita il valore tra il minimo (0.0) e il massimo (1.0). Poiché 1.2 è superiore a 1.0, viene troncato esattamente a 1.0."
  },
  {
   "codice": "extends RefCounted


func run():
	var mask_value: float = 0.4
	var threshold: float = 0.5
	var visible: bool = mask_value < threshold
	return visible
",
   "domanda": "Che valore booleano restituisce `run()`?",
   "spiegazione": "Confrontiamo il valore del pixel della maschera (0.4) con la soglia dello shader (0.5). Poiché 0.4 è minore di 0.5, la condizione è vera (`true`)."
  },
  {
   "codice": "extends RefCounted


func run():
	var current: float = 0.2
	var speed: float = 0.5
	var delta: float = 1.0
	current += speed * delta
	return current
",
   "domanda": "Quanto vale `current` alla fine?",
   "spiegazione": "`speed * delta` fa `0.5`. Aggiunto a `current` (0.2), dà come risultato `0.7`."
  },
  {
   "codice": "extends RefCounted


func run():
	var color_val: Color = Color(0.5, 0.5, 0.5, 1.0)
	var gray: float = (color_val.r + color_val.g + color_val.b) / 3.0
	return gray
",
   "domanda": "Quanto vale `gray` alla fine?",
   "spiegazione": "Sommiamo le tre componenti RGB (0.5 + 0.5 + 0.5 = 1.5) e dividiamo per 3.0, ottenendo 0.5, che rappresenta l'intensità del grigio."
  }
